   services.nextcloud = {
     enable = true;
-    package = pkgs.nextcloud33;
+    package = pkgs.nextcloud34;
     hostName = "nextcloud.hgeorgiev.com";

     # Use SQLite as backend database

1	# Claude Code CLI
2	#
3	# Claude Code reads MCP servers from ~/.mcp.json or via the --mcp-config flag.
4	# We reuse the MCP configuration generated at ~/.config/mcp/mcp.json by
5	# aliasing `claude` in a zsh snippet sourced from ~/.zshrc.
6	{ pkgs, lib, ... }:
7	{
8	  imports = [ ../mcp ];
9	
10	  home.packages = [ pkgs.claude-code ];
11	
12	  home.file.".claude/settings.json".text = lib.generators.toJSON { } {
13	    theme = "dark";
14	    model = "claude-opus-4-8[1m]";
15	    skipDangerousModePermissionPrompt = true;
16	    includeCoAuthoredBy = false;
17	    effortLevel = "xhigh";
18	    env = {
19	      CLAUDE_CODE_DISABLE_ALTERNATE_SCREEN = "1";
20	      CLAUDE_CODE_DISABLE_FEEDBACK_SURVEY = "1";
21	      # effortLevel above is ignored while Opus 4.8's "launch effort pin"
22	      # is active (it forces the per-model default of "high"). The env var
23	      # takes top precedence and overrides the pin.
24	      CLAUDE_CODE_EFFORT_LEVEL = "xhigh";
25	    };
26	  };
27	
28	  xdg.configFile."zsh/claude.zsh".text = ''
29	    alias claude="claude --mcp-config ~/.config/mcp/mcp.json --dangerously-skip-permissions"
30	  '';
31	}
